// TH15 st04bs BossCard4 「片翼の白鷺」
// 源: st04bs.ecl.txt:1667-1760 (BossCard4) + 1762-1812 (BossCard4_at)
// 入口 Boss 状态: st04bs.ecl.txt:727-753; 过渡时 Boss 在 (0,144), lifeSet 3400。

const TIME_LIMIT: int = 3724;      // 120 开场缓冲 + 3600 源时限 + 4 启动余量
const OPENING_BUFFER: int = 120;

// BossCard4_at: laserNew(0, 0, 640, 0, 16) → Line 判定段 [0.1L, 0.9L] = [64, 576], w=16 → 目标 width=8
const LASER_LEN: fx = 576fx;
const LASER_NEAR: fx = 64fx;
const LASER_WIDTH: fx = 8fx;
const LASER_COLOR: int = 13;       // 源 etSprite(0, 8, 13) 的色号
const LASER_ACTIVE: int = 190;     // 60 帧 WAIT + 120 帧 ACCEL，尾部留 10 帧余量
const ACCEL_FRAMES: int = 120;     // 源 etEx ACCEL a=120
const PI_BAM: int = 32768;         // %A = 3.141593f
const HALF_PI_BAM: int = 16384;    // circlePos 的 ±π/2
const ANG_40_BAM: int = 7282;      // 0.6981317f
const STEP_BAM: int = 2185;        // %B/30 = 2π/30
const FLAG_PHASE_ENDED: int = GLOBALS_SYS_SEGMENT;  // control 段结束后通知 Boss 退场

// 源 laserOn 复制的发射器 EX: WAIT 60 之后按 ACCEL 沿各自弹角加速平移。
// 目标没有激光速度写口，用公开 lz_origin 逐帧推进原点（整条判定段随原点平移）。
async sub beam_motion(l1: int, l2: int, l3: int, l4: int,
                      ox1: fx, oy1: fx, ox2: fx, oy2: fx, base: angle, accel: fx) {
    wait(60);                      // 源 etEx WAIT 60
    var v: fx = 0fx;
    var disp: fx = 0fx;
    var ux0: fx = cos(base);
    var uy0: fx = sin(base);
    var uxp: fx = cos(base + 40deg);
    var uyp: fx = sin(base + 40deg);
    var uxm: fx = cos(base - 40deg);
    var uym: fx = sin(base - 40deg);
    for i in 0..ACCEL_FRAMES {
        // 段结束清弹会回收已建激光；先探活，避免对死句柄写原点
        if lz_alive(l1) == 0 { return; }
        v = v + accel;             // 源 etEx ACCEL r（逐难度 0.05/0.1/0.12/0.1）
        disp = disp + v;
        lz_origin(l1, ox1 + disp * ux0, oy1 + disp * uy0);
        lz_origin(l2, ox1 + disp * uxp, oy1 + disp * uyp);
        lz_origin(l3, ox2 + disp * ux0, oy2 + disp * uy0);
        lz_origin(l4, ox2 + disp * uxm, oy2 + disp * uym);
        wait(1);
    }
}

async sub boss_card() {
    set_invuln(65535);
    set_hitbox(24fx);              // 源 setHitbox(48,48) 普通圆取第一值×0.5
    set_hurtbox(20fx);             // 源 setHurtbox(40,40)

    var rank: int = global(GVAR_RANK);
    var t_first: int = 60;         // 源 movePosTime 到 y=192 的时长 (E60 N60 H40 LO40)
    var t_second: int = 120;       // 源 movePosTime 到 y=64 的时长 (E160 N160 H150 LO120)
    var n_burst: int = 40;         // 源 diffI($E, 20, 40, 40, 40)
    var period: int = 3;           // 源 wait (8/4/4/3)
    var steps: int = 1;            // Easy 每轮多一次 %A += %B/30
    var accel: fx = 0.1fx;         // 源 ACCEL r (0.05/0.1/0.12/0.1)
    if rank == RANK_EASY {
        t_second = 160;
        n_burst = 20;
        period = 8;
        steps = 2;
        accel = 0.05fx;
    } else if rank == RANK_NORMAL {
        t_second = 160;
        period = 4;
    } else if rank == RANK_HARD {
        t_first = 40;
        t_second = 150;
        period = 4;
        accel = 0.12fx;
    } else {
        t_first = 40;
    }

    // 源入口 movePosTime(60, 4, 0, 144) 原地不动；+60 标签后才进发弹循环
    wait(60);

    var a_bam: int = PI_BAM;       // %A
    var c: fx = -128fx;            // %C
    var sgn: int = 1;              // %B 的符号（±2π）
    loop {
        if global(FLAG_PHASE_ENDED) != 0 { return; }
        var x1: fx = c - 48fx + (rand(97) as fx);        // %C + %RANDF2*48
        move_to(t_first, x1, 192fx, EASE_QUAD_OUT);      // 源 mode 4 二次减速
        wait(t_first);
        var x2: fx = 0fx - c - 16fx + (rand(33) as fx);  // -%C + %RANDF2*16
        move_to(t_second, x2, 64fx, EASE_QUAD_IN_OUT);   // 源 mode 9
        wait(t_second);

        for k in 0..n_burst {                            // @BossCard4_at(%A, %B)
            if global(FLAG_PHASE_ENDED) != 0 { return; }
            var a: angle = a_bam as angle;
            // circlePos(%C, %D, A ± π/2, 20)：两对激光原点在同一层垂线上偏 ±20
            var o1x: fx = 20fx * cos((a_bam + HALF_PI_BAM) as angle);
            var o1y: fx = 20fx * sin((a_bam + HALF_PI_BAM) as angle);
            var o2x: fx = 20fx * cos((a_bam - HALF_PI_BAM) as angle);
            var o2y: fx = 20fx * sin((a_bam - HALF_PI_BAM) as angle);
            var px: fx = $self_x;
            var py: fx = $self_y;
            var l1: int = laser(LASER_COLOR, px + o1x, py + o1y, a,
                                LASER_LEN, LASER_WIDTH, 0, LASER_ACTIVE, 0);
            lz_start(l1, LASER_NEAR);
            var l2: int = laser(LASER_COLOR, px + o1x, py + o1y, (a_bam + ANG_40_BAM) as angle,
                                LASER_LEN, LASER_WIDTH, 0, LASER_ACTIVE, 0);
            lz_start(l2, LASER_NEAR);
            var l3: int = laser(LASER_COLOR, px + o2x, py + o2y, a,
                                LASER_LEN, LASER_WIDTH, 0, LASER_ACTIVE, 0);
            lz_start(l3, LASER_NEAR);
            var l4: int = laser(LASER_COLOR, px + o2x, py + o2y, (a_bam - ANG_40_BAM) as angle,
                                LASER_LEN, LASER_WIDTH, 0, LASER_ACTIVE, 0);
            lz_start(l4, LASER_NEAR);
            spawn beam_motion(l1, l2, l3, l4,
                              px + o1x, py + o1y, px + o2x, py + o2y, a, accel);
            a_bam = a_bam + STEP_BAM * steps * sgn;      // %A += %B/30
            wait(period);
        }
        a_bam = PI_BAM - a_bam;                          // %A = π - %A
        c = 0fx - c;                                     // %C = -%C
        sgn = 0 - sgn;                                   // %B = -%B
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 144fx, 3400, 0, 0, 0, boss_card);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    set_global(FLAG_PHASE_ENDED, 1);
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
